        if xmlDictOwns((*hash).dict, key) != 0 {
            copy = key as *mut xmlChar;
        } else {
            copy = xmlDictLookup((*hash).dict, key, -(1 as c_int)) as *mut xmlChar;
            if copy.is_null() {
                return -(1 as c_int);
            }
        }
