            copy2 = key2 as *mut xmlChar;
        } else {
            copy2 = xmlDictLookup((*hash).dict, key2, -(1 as c_int)) as *mut xmlChar;
            if copy2.is_null() {
                return -(1 as c_int);
            }
        }
