            return -(1 as c_int);
        }
        memcpy(
            copy as *mut c_void,
            key as *const c_void,
            lengths[0 as c_int as usize].wrapping_add(1 as size_t),
        );
        if !key2.is_null() {
            copy2 = xmlMalloc.expect("non-null function pointer")(
                lengths[1 as c_int as usize].wrapping_add(1 as size_t),
