            memmove(
                (*hash).table.offset(1 as c_int as isize) as *mut xmlHashEntry
                    as *mut c_void,
                (*hash).table as *const c_void,
                (cur as *mut c_char)
                    .offset_from((*hash).table as *mut c_char)
                    as c_long as size_t,
            );
            cur = end.offset(-(1 as c_int as isize));
            *(*hash).table.offset(0 as c_int as isize) = *cur;
